steps.codeExample:
const vendas = [10, 20, 10, 50];

// Remover duplicatas com Set nativo
const unicos = [...new Set(vendas)]; // [10, 20, 50]

// Somar valores com reduce
const total = unicos.reduce((acc, val) => acc + val, 0); // 80

// Converter objeto para JSON
const payload = JSON.stringify({ total, max: Math.max(...unicos) });

